components.css:
.capture-page-actions {
  margin-top: 16px;
}
.capture-organize {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 36px;
  padding: 8px 0;
  border: 0;
  background: transparent;
  color: var(--theme-accent);
  font: inherit;
  font-size: 13px;
  cursor: pointer;
}
.capture-organize:hover {
  text-decoration: underline;
  text-underline-offset: 3px;
}
.detail-panel.capture-import-panel {
  padding: 22px;
  background: var(--theme-surface);
}
.capture-page-import {
  display: flex;
  flex-direction: column;
  gap: 16px;
  min-width: 0;
  outline: none;
  color: var(--theme-ink);
}
.capture-page-import *,
.capture-page-import *::before,
.capture-page-import *::after {
  box-sizing: border-box;
}
.capture-page-import button {
  cursor: pointer;
  font: inherit;
  font-size: 13px;
}
.capture-page-import .capture-import-heading {
  display: flex;
  align-items: center;
  justify-content: flex-start;
  gap: 8px;
}
.capture-page-import .capture-import-heading h2 {
  margin: 0;
  font-size: 18px;
  letter-spacing: -0.02em;
}
.capture-page-import .capture-import-heading button {
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  flex-shrink: 0;
  border: 0;
  border-radius: 6px;
  padding: 0;
  background: transparent;
  color: var(--theme-muted);
}
.capture-page-import .capture-import-heading button:hover {
  background: var(--theme-soft);
}
.capture-page-import .capture-import-help {
  margin: -8px 0 0;
  color: var(--theme-muted);
  font-size: 12px;
  line-height: 1.65;
}
.capture-page-import .capture-import-preview {
  border-block: 1px solid var(--theme-line);
  font-size: 12px;
}
.capture-page-import .capture-import-preview summary {
  cursor: pointer;
  padding: 12px 0;
  color: var(--theme-ink);
}
.capture-page-import .capture-import-preview summary small {
  display: inline-block;
  margin-left: 10px;
  color: var(--theme-muted);
  font-size: 11px;
}
.capture-page-import .capture-import-preview .ai-result-reading {
  padding-block: 8px 16px;
  font-size: 13px;
}
.capture-page-import .capture-import-original {
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  margin: 0 0 14px;
  line-height: 1.7;
}
.capture-page-import .capture-import-form {
  display: flex;
  flex-direction: column;
  gap: 16px;
  min-width: 0;
}
.capture-page-import .capture-import-modes {
  display: flex;
  gap: 4px;
  padding: 4px;
  background: var(--theme-raised);
  border-radius: 7px;
}
.capture-page-import .capture-import-modes button {
  flex: 1;
  min-height: 34px;
  border: 0;
  padding: 6px 10px;
  border-radius: 5px;
  color: var(--theme-muted);
  background: transparent;
}
.capture-page-import .capture-import-modes button[aria-pressed='true'] {
  background: var(--theme-surface);
  color: var(--theme-accent);
  box-shadow: 0 1px 3px rgb(0 0 0 / 0.07);
}
.capture-page-import .capture-import-modes strong {
  font-weight: 600;
}
.capture-page-import .capture-import-title {
  display: grid;
  gap: 7px;
  color: var(--theme-ink);
  font-size: 12px;
  font-weight: 600;
}
.capture-page-import .capture-import-title input,
.capture-page-import .capture-import-search {
  min-height: 40px;
  border: 1px solid var(--theme-line);
  border-radius: 7px;
  color: var(--theme-ink);
  background: var(--theme-surface);
}
.capture-page-import .capture-import-title input {
  width: 100%;
  min-width: 0;
  padding: 8px 11px;
  font: inherit;
  font-size: 14px;
  font-weight: 400;
}
.capture-page-import h3 {
  margin: 0 0 8px;
  font-size: 12px;
  font-weight: 600;
}
.capture-page-import .capture-import-destination {
  min-width: 0;
  border: 1px solid var(--theme-line);
  border-radius: 7px;
  padding: 0 12px;
}
.capture-page-import .capture-import-destination > summary {
  cursor: pointer;
  padding: 12px 0;
  font-size: 12px;
  overflow-wrap: anywhere;
}
.capture-page-import .capture-import-destination > summary strong {
  margin-left: 10px;
  font-size: 13px;
  color: var(--theme-accent);
  font-weight: 500;
}
.capture-page-import .capture-import-destination[open] {
  padding-bottom: 8px;
}
.capture-page-import .capture-import-search {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 0 10px;
  color: var(--theme-muted);
}
.capture-page-import .capture-import-search input {
  width: 100%;
  min-width: 0;
  border: 0;
  outline: 0;
  padding: 9px 0;
  background: transparent;
  color: var(--theme-ink);
  font: inherit;
  font-size: 13px;
}
.capture-page-import .capture-import-search:focus-within {
  border-color: var(--theme-accent);
}
.capture-page-import input::placeholder {
  color: var(--theme-muted);
  opacity: 1;
}
.capture-page-import .capture-import-results {
  margin-top: 6px;
  min-width: 0;
}
.capture-page-import .capture-import-result {
  display: flex;
  align-items: center;
  gap: 9px;
  width: 100%;
  min-height: 44px;
  padding: 7px 8px;
  border: 0;
  border-radius: 5px;
  background: transparent;
  color: var(--theme-ink);
  text-align: left;
}
.capture-page-import .capture-import-result:hover,
.capture-page-import .capture-import-result.is-selected {
  background: var(--theme-soft);
}
.capture-page-import .capture-import-result > span:first-child,
.capture-page-import .capture-import-result > svg {
  flex-shrink: 0;
}
.capture-page-import .capture-import-result > span:nth-child(2) {
  flex: 1;
  min-width: 0;
}
.capture-page-import .capture-import-result strong,
.capture-page-import .capture-import-result small {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.capture-page-import .capture-import-result strong {
  font-size: 13px;
  font-weight: 500;
}
.capture-page-import .capture-import-result small {
  margin-top: 2px;
  font-size: 11px;
  color: var(--theme-muted);
}
.capture-page-import .capture-import-results > p,
.capture-page-import .capture-import-pending p {
  font-size: 12px;
  color: var(--theme-muted);
  line-height: 1.7;
}
.capture-page-import .capture-import-more {
  width: 100%;
  min-height: 36px;
  border: 0;
  color: var(--theme-accent);
  background: transparent;
}
.capture-page-import .capture-import-selected {
  display: flex;
  align-items: flex-start;
  gap: 6px;
  margin: 0 0 8px;
  font-size: 11px;
  line-height: 1.6;
  color: var(--theme-muted);
  overflow-wrap: anywhere;
}
.capture-page-import .capture-import-selected svg {
  flex-shrink: 0;
  margin-top: 2px;
}
.capture-page-import .capture-import-options label {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 36px;
  font-size: 12px;
}
.capture-page-import .capture-import-options p {
  display: flex;
  align-items: center;
  gap: 6px;
  margin: 0 0 7px;
  color: var(--theme-accent);
  font-size: 12px;
}
.capture-page-import .capture-import-options input {
  width: 16px;
  height: 16px;
  flex-shrink: 0;
  accent-color: var(--theme-accent);
}
.capture-page-import .capture-import-options label span {
  min-width: 0;
  overflow-wrap: anywhere;
}
.capture-page-import .capture-import-options small {
  display: block;
  margin-top: 2px;
  color: var(--theme-muted);
  font-size: 11px;
}
.capture-page-import .capture-import-footer {
  position: sticky;
  bottom: 0;
  margin: 0;
  padding: 12px 0 max(8px, env(safe-area-inset-bottom));
  border-top: 1px solid var(--theme-line);
  background: var(--theme-surface);
}
.capture-page-import .capture-import-footer > p {
  margin: 0 0 10px;
  font-size: 11px;
  line-height: 1.6;
  color: var(--theme-muted);
}
.capture-page-import .capture-import-submit {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 40px;
  padding: 9px 12px;
  border: 0;
  border-radius: 7px;
  background: var(--theme-accent);
  color: var(--theme-accent-ink);
  font-weight: 600;
}
.capture-page-import .capture-import-submit:hover:not(:disabled) {
  background: var(--theme-accent);
  filter: brightness(0.94);
}
.capture-page-import button:disabled {
  cursor: default;
  opacity: 0.5;
}
.capture-page-import :is(button, summary):focus-visible,
.capture-page-import label:has(input[type='checkbox']:focus-visible) {
  outline: none;
  text-decoration: underline;
  text-underline-offset: 4px;
}
.capture-page-import input:focus-visible {
  outline: none;
  border-color: var(--theme-accent);
}
.capture-page-import .capture-import-search input:focus-visible {
  border: 0;
}
.capture-page-import .capture-import-error {
  margin: 0 0 10px;
  padding: 10px;
  border-radius: 6px;
  background: var(--theme-error-surface);
  color: var(--theme-error-ink);
  font-size: 12px;
  line-height: 1.6;
}
.capture-page-import .capture-import-error button {
  display: block;
  min-height: 36px;
  border: 0;
  background: transparent;
  color: inherit;
  text-decoration: underline;
}
.capture-page-import .capture-import-pending {
  overflow-wrap: anywhere;
}
.capture-page-import .capture-import-return {
  min-height: 40px;
  padding: 8px 12px;
  border: 0;
  border-radius: 7px;
  background: var(--theme-soft);
  color: var(--theme-accent);
}
@media (max-width: 760px) {
  .detail-panel.capture-import-panel {
    padding: 18px;
  }
  .capture-page-import {
    gap: 14px;
  }
  .capture-page-import .capture-import-heading button,
  .capture-page-import .capture-import-modes button,
  .capture-page-import .capture-import-result,
  .capture-page-import .capture-import-submit,
  .capture-page-import .capture-import-options label {
    min-height: 44px;
  }
  .capture-page-import .capture-import-title input,
  .capture-page-import .capture-import-search input {
    font-size: 16px;
  }
  .capture-page-import .capture-import-preview summary small {
    display: block;
    margin: 4px 0 0 14px;
  }
}

.record-timestamps {
  display: flex;
  flex-wrap: wrap;
  gap: 6px 18px;
  margin: 12px 0 0;
  color: var(--theme-muted);
  font-size: 12px;
  line-height: 1.6;
  font-variant-numeric: tabular-nums;
}
.record-timestamps > div {
  display: flex;
  gap: 6px;
  white-space: nowrap;
}
.record-timestamps dt {
  font-weight: 500;
}
.record-timestamps dd {
  margin: 0;
}

.ai-job-panel {
  border-top: 1px solid var(--theme-line);
  margin-top: 28px;
  padding-top: 22px;
  color: var(--theme-ink);
}
.ai-request-summary {
  display: grid;
  gap: 7px;
  margin: 12px 0 20px;
  padding: 12px 0;
  border-block: 1px solid var(--theme-line);
  font-size: 12px;
  line-height: 1.6;
}
.ai-request-summary > div { display: grid; grid-template-columns: 72px minmax(0, 1fr); gap: 10px; }
.ai-request-summary dt { color: var(--theme-muted); }
.ai-request-summary dd { margin: 0; overflow-wrap: anywhere; }
.ai-request-summary small { margin-left: 8px; color: var(--theme-muted); font-size: inherit; }
.ai-request-additional dd { white-space: pre-wrap; }
.ai-result-view { display: flex; gap: 4px; margin: 8px 0 16px; }
.ai-job-panel .ai-result-view button,
.page-ai-panel .ai-result-view button {
  min-height: 30px;
  padding: 4px 9px;
  border: 0;
  border-radius: 5px;
  color: var(--theme-muted);
  background: transparent;
  font-size: 12px;
}
.ai-job-panel .ai-result-view button[aria-pressed='true'],
.page-ai-panel .ai-result-view button[aria-pressed='true'] { color: var(--theme-accent); background: var(--theme-soft); font-weight: 600; }
.ai-result-reading { font-size: 14px; line-height: 1.75; overflow-wrap: anywhere; }
.ai-result-reading > :first-child { margin-top: 0; }
.ai-result-reading h1 { font-size: 23px; }
.ai-result-reading h2 { font-size: 19px; }
.ai-result-reading h3 { font-size: 16px; }
.ai-result-reading :is(h1,h2,h3,h4,h5,h6) { margin: 24px 0 10px; line-height: 1.4; font-weight: 650; word-break: keep-all; }
.ai-result-reading p { margin: 10px 0; }
.ai-result-reading :is(ul,ol) { padding-left: 24px; margin: 10px 0; }
.ai-result-reading li { padding-left: 2px; margin: 5px 0; }
.ai-result-reading a { color: var(--theme-accent); text-underline-offset: 3px; }
.ai-result-reading blockquote { margin: 14px 0; padding: 8px 12px; border: 1px solid var(--theme-line); border-radius: 6px; color: var(--theme-muted); }
.ai-result-reading code { font-family: ui-monospace, monospace; font-size: .9em; background: var(--theme-raised); padding: 2px 4px; border-radius: 4px; }
.ai-result-reading pre { padding: 14px; border-radius: 6px; background: var(--theme-raised); overflow-x: auto; }
.ai-result-reading pre code { padding: 0; background: transparent; }
.ai-result-reading hr { border: 0; border-top: 1px solid var(--theme-line); margin: 20px 0; }
.ai-result-table { overflow-x: auto; max-width: 100%; }
.ai-result-reading table { border-collapse: collapse; width: 100%; font-size: 13px; }
.ai-result-reading :is(th,td) { text-align: left; padding: 8px 10px; border-bottom: 1px solid var(--theme-line); min-width: 80px; }
.ai-result-reading th { background: var(--theme-raised); }
.ai-result-check-item { list-style: none; position: relative; }
.ai-result-check-item > input { position: absolute; left: -21px; top: 7px; accent-color: var(--theme-accent); }
.ai-result-image-label { color: var(--theme-muted); font-style: italic; }
@media (max-width: 760px) {
  .ai-job-panel .ai-result-view button,
  .page-ai-panel .ai-result-view button { min-height: 44px; }
}

.ai-job-heading {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 10px;
}
.ai-job-heading h2 {
  display: flex;
  align-items: center;
  gap: 7px;
  margin: 0;
  font-size: 16px;
}
.ai-job-state {
  font-size: 12px;
  font-weight: 600;
  white-space: nowrap;
  color: var(--theme-muted);
}
.ai-saved-prompt > summary {
  display: list-item;
  list-style: disclosure-closed inside;
  color: var(--theme-muted);
}
.ai-saved-prompt[open] > summary {
  list-style-type: disclosure-open;
}
.ai-job-panel button:focus-visible, .ai-job-panel summary:focus-visible, .ai-result-sources a:focus-visible { outline: none; text-decoration: underline; text-underline-offset: 4px; }
.ai-execution-picker select:focus-visible { outline: none; border-color: var(--theme-accent); }
.ai-followup :focus-visible { outline: none; }
.ai-followup :is(button, summary):focus-visible, .ai-followup label:has(input:focus-visible) { text-decoration: underline; text-underline-offset: 4px; }
.ai-followup :is(textarea, select):focus-visible { border-color: var(--theme-accent); }
